def add(s, q, o, e, k="one", n=False, c=False, a=None, **x):
    d = dict(s=s, q=q, o=o, e=e, k=k, n=n, c=c, a=a); d.update(x); Q.append(d)

def past(y, q):
    """An exact past question, taken from the tagged data (first option is the right one)."""
    r = [r for r in _past.ROWS if r[0] == y and r[1] == q][0]
    opts = list(r[9]); right = "ABCD".index(r[6])
    return r[8], [opts[right]] + [x for i, x in enumerate(opts) if i != right]

